def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    max_prev = 0.0
    eric_like = 0.0
    cindy_like = 0.0
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        alive.append(opp)
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = 0.0
        if prev and prev.get('bid') is not None:
            bid = float(prev.get('bid', 0.0))
            prev_bids.append(bid)
            if bid > max_prev:
                max_prev = bid
        oid = str(opp_id).lower()
        if oid == 'eric':
            eric_like = bid
        if oid == 'cindy':
            cindy_like = bid

    if not alive:
        return float(min(budget, 18.0))

    slots = supply / float(WATER_REQ)

    if hp <= 2 or no_water >= 2:
        target = max(62.0, eric_like + 3.0)
        if cindy_like > 0:
            target = min(target, cindy_like * 0.72)
        return float(max(0.0, min(budget, target)))

    if hp <= 4 or no_water >= 1:
        if slots >= 1.7:
            target = max(36.0, eric_like + 2.0)
        else:
            target = max(52.0, eric_like + 4.0, max_prev * 0.92)
        if cindy_like >= 120.0:
            target = min(target, cindy_like * 0.68)
        return float(max(0.0, min(budget, target)))

    if slots >= 1.8:
        base = 14.0
    elif slots >= 1.5:
        base = 21.0
    else:
        base = 29.0

    if max_prev >= 110.0:
        base -= 4.0
    elif max_prev <= 20.0 and urgent_opp == 0:
        base += 6.0

    if eric_like > 0:
        if eric_like <= 35.0:
            base = max(base, eric_like + 1.5)
        elif eric_like <= 70.0:
            base = max(base, eric_like * 0.78)
        else:
            base = min(base, eric_like * 0.62)

    if cindy_like >= 120.0:
        base = min(base, 34.0)

    if len(alive) >= 3 and slots < 1.4:
        base += 6.0

    safe_cap = budget
    if hp >= 7 and no_water == 0:
        safe_cap = min(safe_cap, DAILY_SALARY * 0.55)

    bid = max(0.0, min(safe_cap, base))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Safety checks
    my_budget = float(my_status.get('budget', 0.0))
    my_hp = float(my_status.get('hp', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # If we are in immediate danger, bid aggressively but still bounded by budget.
    if my_hp <= 2 or my_no_water_days >= 2:
        return min(my_budget, DAILY_SALARY * 0.95)

    # Analyze yesterday bids from alive opponents to infer aggressiveness.
    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid depends on supply: with more supply, we can bid lower yet still win.
    # supply is float, but we only use it for comparisons.
    supply_frac = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_frac < 0:
            supply_frac = 0.0
        if supply_frac > 1:
            supply_frac = 1.0

    # If opponents were aggressive yesterday, slightly increase bid; otherwise stay conservative.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Cindy-like behavior: very high bids.
        if highest_prev_bid >= DAILY_SALARY * 1.2:
            # Still not matching; aim to secure water without burning budget.
            bid = DAILY_SALARY * (0.45 + 0.15 * supply_frac)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            bid = DAILY_SALARY * (0.40 + 0.10 * supply_frac)
        else:
            bid = DAILY_SALARY * (0.35 + 0.08 * supply_frac)
    else:
        bid = DAILY_SALARY * (0.35 + 0.08 * supply_frac)

    # Ensure we don't bid more than budget.
    if my_budget <= 0:
        return 0.0

    # If budget is low, reduce further.
    budget_frac = my_budget / (DAILY_SALARY + 1e-9)
    if budget_frac < 0.4:
        bid = min(bid, my_budget * 0.9)

    # Final clamp.
    return float(min(my_budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Base bid, adjusted by HP
    base_bid = DAILY_SALARY * 0.5
    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] <= 7:
        base_bid = DAILY_SALARY * 0.7

    # Look at yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If highest bid was very high, we might need to exceed it
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 3:
                base_bid = max(base_bid, highest_prev_bid + 5.0)
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 1.0)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.4)

    # Adjust for remaining days
    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.6)
    elif day_context['day'] <= 3:
        if my_status['hp'] <= 3:
            base_bid = max(base_bid, DAILY_SALARY * 0.85)

    final_bid = min(my_status['budget'], base_bid)
    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
